CREATE TABLE system_configs (id UUID PRIMARY KEY, key TEXT NOT NULL UNIQUE, value TEXT NOT NULL, type TEXT NOT NULL, description TEXT, updated_by UUID, updated_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE alerts (id UUID PRIMARY KEY, scope TEXT NOT NULL, severity TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, detail TEXT, action TEXT, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ, resolved_by UUID);
CREATE TABLE incidents (id UUID PRIMARY KEY, type TEXT NOT NULL, status TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ, duration_ms BIGINT NOT NULL DEFAULT 0, error TEXT, retry_count INTEGER NOT NULL DEFAULT 0, resource_type TEXT, resource_id TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE admin_notes (id UUID PRIMARY KEY, target_type TEXT NOT NULL, target_id UUID NOT NULL, author_id UUID NOT NULL, body TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE export_jobs (id UUID PRIMARY KEY, requester UUID NOT NULL, kind TEXT NOT NULL, filters JSONB, status TEXT NOT NULL, file_ref TEXT, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE saved_views (id UUID PRIMARY KEY, user_id UUID NOT NULL, page TEXT NOT NULL, name TEXT NOT NULL, filters JSONB, shared BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE verification_overrides (id UUID PRIMARY KEY, request_id UUID NOT NULL, admin_id UUID NOT NULL, reason TEXT NOT NULL, step_up_receipt TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE public_proof_verification_logs (id UUID PRIMARY KEY, proof_id UUID NOT NULL, checked_at TIMESTAMPTZ NOT NULL, overall TEXT NOT NULL, failed_checks TEXT, ip_hash TEXT);
